/**
 * @kartik/agent/agents/pdf — Structured PDF Document Generator & Standards-Compliant PDF 1.4 Binary Builder
 * (Blueprint §4.1, §7.2 Phase 10 & Tutorial Part 2).
 *
 * Generates a real downloadable multi-page `.pdf` binary (`%PDF-1.4` with Catalog, Pages, Page objects,
 * Helvetica / Helvetica-Bold fonts, wrapped text streams, navy/cyan title banner, bullet points,
 * page numbering `Page X of Y`, `"Generated by Kartik.ai"` footer, and exact byte-offset `xref` table).
 */

import {
  validatePdfDocumentSpec,
  type PdfDocumentSpec,
  type PdfSectionSpec,
} from '../../schemas/index.js';

export interface PdfDocumentGenerationResult {
  readonly spec: PdfDocumentSpec;
  readonly pdfBytes: Uint8Array;
  readonly pageCount: number;
  readonly summaryMarkdown: string;
  readonly tokensUsed: number;
}

export interface PdfDocumentProvider {
  readonly providerName: string;
  generatePdfDocument(input: {
    readonly prompt: string;
    readonly maxOutputTokens: number;
  }): Promise<PdfDocumentGenerationResult>;
}

/**
 * Escapes characters that have special meaning inside a PDF literal string `(...)`.
 */
function escapePdfLiteral(text: string): string {
  return text
    .replace(/[^\x20-\x7E]/g, ' ')
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)');
}

/**
 * Word-wraps a paragraph into lines of at most `maxCharsPerLine` characters.
 */
function wrapTextToLines(text: string, maxCharsPerLine: number): string[] {
  const words = text.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) {
    return [];
  }
  const lines: string[] = [];
  let current = words[0]!;
  for (let i = 1; i < words.length; i++) {
    const word = words[i]!;
    if (current.length + 1 + word.length <= maxCharsPerLine) {
      current += ` ${word}`;
    } else {
      lines.push(current);
      current = word;
    }
  }
  lines.push(current);
  return lines;
}

interface PdfLineOperation {
  readonly font: 'F1' | 'F2';
  readonly size: number;
  readonly colorRgb: readonly [number, number, number];
  readonly indentX: number;
  readonly text: string;
  readonly spacingBefore: number;
  readonly spacingAfter: number;
}

/**
 * Compiles a validated `PdfDocumentSpec` into a standards-compliant `%PDF-1.4` binary buffer
 * with automatic pagination, header/footer rendering, and exact `xref` byte offsets.
 */
export function buildPdfBinaryBuffer(rawSpec: PdfDocumentSpec): {
  readonly pdfBytes: Buffer;
  readonly pageCount: number;
  readonly spec: PdfDocumentSpec;
} {
  const spec = validatePdfDocumentSpec(rawSpec);
  const ops: PdfLineOperation[] = [];

  // Document Title & Subtitle (matching Tutorial Part 2 styling: #1A1A2E title, #555555 subtitle)
  for (const line of wrapTextToLines(spec.title, 54)) {
    ops.push({
      font: 'F2',
      size: 20,
      colorRgb: [0.1, 0.1, 0.18],
      indentX: 50,
      text: line,
      spacingBefore: 4,
      spacingAfter: 6,
    });
  }

  for (const line of wrapTextToLines(spec.subtitle, 74)) {
    ops.push({
      font: 'F1',
      size: 11,
      colorRgb: [0.33, 0.33, 0.38],
      indentX: 50,
      text: line,
      spacingBefore: 2,
      spacingAfter: 14,
    });
  }

  // Document Sections
  for (let idx = 0; idx < spec.sections.length; idx++) {
    const section = spec.sections[idx]!;
    const numberedHeading = `${idx + 1}. ${section.heading}`;
    for (const line of wrapTextToLines(numberedHeading, 64)) {
      ops.push({
        font: 'F2',
        size: 14,
        colorRgb: [0.09, 0.13, 0.24],
        indentX: 50,
        text: line,
        spacingBefore: 10,
        spacingAfter: 4,
      });
    }

    for (const line of wrapTextToLines(section.content, 82)) {
      ops.push({
        font: 'F1',
        size: 10.5,
        colorRgb: [0.15, 0.15, 0.15],
        indentX: 50,
        text: line,
        spacingBefore: 1,
        spacingAfter: 3,
      });
    }

    for (const bullet of section.bullets) {
      const wrappedBullet = wrapTextToLines(bullet, 76);
      wrappedBullet.forEach((bLine, bIdx) => {
        ops.push({
          font: 'F1',
          size: 10,
          colorRgb: [0.18, 0.2, 0.24],
          indentX: bIdx === 0 ? 64 : 74,
          text: bIdx === 0 ? `- ${bLine}` : bLine,
          spacingBefore: 1,
          spacingAfter: 2,
        });
      });
    }
  }

  // Paginate operations across A4 pages (595.28 x 841.89 pt, top Y = 775, bottom Y = 70)
  const pagesOps: PdfLineOperation[][] = [];
  let currentPage: PdfLineOperation[] = [];
  let cursorY = 770;

  for (const op of ops) {
    const requiredHeight = op.spacingBefore + op.size + op.spacingAfter;
    if (cursorY - requiredHeight < 75 && currentPage.length > 0) {
      pagesOps.push(currentPage);
      currentPage = [];
      cursorY = 770;
    }
    currentPage.push(op);
    cursorY -= requiredHeight;
  }
  if (currentPage.length > 0 || pagesOps.length === 0) {
    pagesOps.push(currentPage);
  }

  const totalPages = pagesOps.length;

  // Object IDs:
  // 1: Catalog
  // 2: Pages
  // 3: Font F1 (/Helvetica)
  // 4: Font F2 (/Helvetica-Bold)
  // For each page i (0..totalPages-1):
  //   pageObjId = 5 + i * 2
  //   contentObjId = 6 + i * 2
  const objects: string[] = [];
  const pageObjectIds: number[] = [];

  for (let i = 0; i < totalPages; i++) {
    pageObjectIds.push(5 + i * 2);
  }

  objects.push(`1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n`);
  objects.push(
    `2 0 obj\n<< /Type /Pages /Kids [${pageObjectIds.map((id) => `${id} 0 R`).join(' ')}] /Count ${totalPages} >>\nendobj\n`,
  );
  objects.push(
    `3 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n`,
  );
  objects.push(
    `4 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>\nendobj\n`,
  );

  for (let pageIdx = 0; pageIdx < totalPages; pageIdx++) {
    const pageOps = pagesOps[pageIdx]!;
    const pageObjId = 5 + pageIdx * 2;
    const contentObjId = 6 + pageIdx * 2;

    const streamLines: string[] = [];
    // Top accent bar on page 1
    if (pageIdx === 0) {
      streamLines.push('0.06 0.09 0.16 rg');
      streamLines.push('50 792 495 4 re f');
    }

    let y = 770;
    for (const op of pageOps) {
      y -= op.spacingBefore + op.size;
      const [r, g, b] = op.colorRgb;
      streamLines.push('BT');
      streamLines.push(`/${op.font} ${op.size.toFixed(1)} Tf`);
      streamLines.push(`${r.toFixed(2)} ${g.toFixed(2)} ${b.toFixed(2)} rg`);
      streamLines.push(`${op.indentX} ${y.toFixed(1)} Td`);
      streamLines.push(`(${escapePdfLiteral(op.text)}) Tj`);
      streamLines.push('ET');
      y -= op.spacingAfter;
    }

    // Footer divider & text ("Generated by Kartik.ai — Page X of Y")
    streamLines.push('0.82 0.84 0.88 RG');
    streamLines.push('0.5 w');
    streamLines.push('50 52 m 545 52 l S');
    streamLines.push('BT');
    streamLines.push('/F1 9.0 Tf');
    streamLines.push('0.50 0.52 0.56 rg');
    streamLines.push('50 38 Td');
    streamLines.push(
      `(${escapePdfLiteral(`${spec.footer}  |  Page ${pageIdx + 1} of ${totalPages}`)}) Tj`,
    );
    streamLines.push('ET');

    const streamContent = streamLines.join('\n') + '\n';
    const streamByteLength = Buffer.byteLength(streamContent, 'ascii');

    objects.push(
      `${pageObjId} 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${contentObjId} 0 R >>\nendobj\n`,
    );
    objects.push(
      `${contentObjId} 0 obj\n<< /Length ${streamByteLength} >>\nstream\n${streamContent}endstream\nendobj\n`,
    );
  }

  let pdfBody = '%PDF-1.4\n';
  const offsets: number[] = [0]; // index 0 is the free object

  for (const objStr of objects) {
    offsets.push(Buffer.byteLength(pdfBody, 'ascii'));
    pdfBody += objStr;
  }

  const xrefOffset = Buffer.byteLength(pdfBody, 'ascii');
  const totalObjCount = objects.length + 1;

  let xref = `xref\n0 ${totalObjCount}\n0000000000 65535 f \n`;
  for (let i = 1; i < offsets.length; i++) {
    const padded = String(offsets[i]!).padStart(10, '0');
    xref += `${padded} 00000 n \n`;
  }

  const trailer = `trailer\n<< /Size ${totalObjCount} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`;
  const pdfBytes = Buffer.from(pdfBody + xref + trailer, 'ascii');

  return Object.freeze({
    pdfBytes,
    pageCount: totalPages,
    spec,
  });
}

/**
 * Formats a clean Markdown summary of the generated PDF document for the assistant message bubble.
 */
export function formatPdfSummaryMarkdown(spec: PdfDocumentSpec, pageCount: number): string {
  const sectionTitles = spec.sections
    .map((s, idx) => `${idx + 1}. **${s.heading}**`)
    .join('\n');
  return [
    `### ${spec.title}`,
    `*${spec.subtitle}*`,
    '',
    `Your structured PDF document (**${pageCount} page${pageCount === 1 ? '' : 's'}**, **${spec.sections.length} sections**) has been generated and is ready to download below:`,
    '',
    sectionTitles,
  ].join('\n');
}

/**
 * Deterministic PDF Document Provider for offline unit tests and `MOCK_AI=true` environments.
 */
export class MockPdfDocumentProvider implements PdfDocumentProvider {
  public readonly providerName = 'mock-pdf';

  public async generatePdfDocument(input: {
    readonly prompt: string;
    readonly maxOutputTokens: number;
  }): Promise<PdfDocumentGenerationResult> {
    const cleanTopic = input.prompt
      .replace(/^(generate|create|write|build|export)\s+(a\s+)?(pdf|report|document)\s*(on|about|for)?\s*/i, '')
      .trim() || 'Multi-Agent System Architecture';

    const titleTopic =
      cleanTopic.charAt(0).toUpperCase() + cleanTopic.slice(1).slice(0, 80);

    const sections: PdfSectionSpec[] = [
      {
        heading: 'Executive Overview & Problem Statement',
        content: `This technical document examines ${titleTopic}, outlining the core architectural principles, service boundaries, and operational trade-offs required for production reliability.`,
        bullets: [
          `Primary domain scope and objectives for ${titleTopic}`,
          'Separation of concerns across stateless API gateways and stateful datastores',
          'Predictable failure handling and idempotent retry semantics',
        ],
      },
      {
        heading: 'Core Architecture & Data Flow',
        content: `A resilient implementation of ${titleTopic} isolates external dependencies behind strict adapter contracts and enforces schema validation at every boundary.`,
        bullets: [
          'Ingress validation and cryptographic request context propagation',
          'Transactional persistence with row-level locking where state is mutated',
          'Short-lived signed URLs for private binary artifacts',
        ],
      },
      {
        heading: 'Security, Rate Limiting & Cost Controls',
        content: `Production deployments of ${titleTopic} require layered rate limiting (per-IP, per-user, and per-specialist) combined with daily budget guards.`,
        bullets: [
          'Zero-trust ownership verification on all user-scoped queries',
          'Sliding-window Redis rate limiters with explicit Retry-After headers',
          'Automated health checks, backups, and reproducible disaster recovery',
        ],
      },
      {
        heading: 'Implementation Checklist & Next Steps',
        content: `Teams adopting ${titleTopic} should verify each phase against automated contract tests before enabling live traffic.`,
        bullets: [
          'Run end-to-end contract tests across all service boundaries',
          'Audit environment configuration and secret redaction policies',
          'Monitor latency percentiles and resource utilization continuously',
        ],
      },
    ];

    const spec = validatePdfDocumentSpec({
      title: `${titleTopic} — Technical Report`,
      subtitle: 'Structured Architecture & Implementation Reference',
      sections,
      footer: 'Generated by Kartik.ai',
    });

    const compiled = buildPdfBinaryBuffer(spec);

    return Object.freeze({
      spec: compiled.spec,
      pdfBytes: compiled.pdfBytes,
      pageCount: compiled.pageCount,
      summaryMarkdown: formatPdfSummaryMarkdown(compiled.spec, compiled.pageCount),
      tokensUsed: 180,
    });
  }
}
